# -*- coding: utf-8 -*-
S = "полный обзор задач 10 класса (очередь G9–G11), проверено вычислением; условия сверены с текстом учебника"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G10_TB_§42_42_4_4", r"$x=3$ не входит в ОДЗ $\sqrt{x-4}$ ($x\ge4$): нуль функции только $x=4$",
  k=r"$x = 4$",
  dnew={1: (r"$x = 3$, $x = 4$", "Ученик взял корень $x=3$ из первого множителя, не проверив ОДЗ: при $x=3$ выражение $\\sqrt{x-4}$ не определено.")})
E("G10_TB_§6_6_9", r"убывание: $(-\frac23)^5\approx-0{,}13>(-\frac34)^5\approx-0{,}24>(-2\frac13)^5\approx-68{,}6>(-2\frac25)^5\approx-79{,}6$; в ключе последние два поменяны местами",
  k=r"$(\dfrac{-2}{3})^{5}, (\dfrac{-3}{4})^{5}, (-2 \dfrac{1}{3})^{5}, (-2 \dfrac{2}{5})^{5}$",
  dnew={2: (r"$(\dfrac{-2}{3})^{5}, (\dfrac{-3}{4})^{5}, (-2 \dfrac{2}{5})^{5}, (-2 \dfrac{1}{3})^{5}$", "Ученик верно расположил дроби $\\frac{-2}{3}$ и $\\frac{-3}{4}$, но для оснований $-2\\frac{2}{5}$ и $-2\\frac{1}{3}$ решил, что большее по модулю основание даёт большее значение; при нечётной степени оно даёт меньшее.")})
E("G10_TB_§7_6_20", r"$9a-a^{3}=a(3-a)(3+a)>0$ при $a<-3$ и $0<a<3$ (два корня), $<0$ при $-3<a<0$ и $a>3$ (корней нет); в ключе знаки были перепутаны",
  k=r"при $a \in (-3; 0) \cup (3; +\infty)$: $0$ корней; при $a = -3$, $a = 0$, $a = 3$: $1$ корень; при $a \in (-\infty; -3) \cup (0; 3)$: $2$ корня",
  dnew={0: (r"при $a \in (-\infty; -3) \cup (0; 3)$: $0$ корней; при $a = -3$, $a = 0$, $a = 3$: $1$ корень; при $a \in (-3; 0) \cup (3; +\infty)$: $2$ корня", "Ученик правильно нашёл нули $9a-a^{3}$, но перепутал знаки на интервалах: где правая часть положительна (два корня), счёл, что корней нет, и наоборот."),
        1: (r"при $a \in (-\infty; 0) \cup (3; +\infty)$: $0$ корней; при $a = 0$, $a = 3$: $1$ корень; при $a \in (0; 3)$: $2$ корня", "Ученик исследовал знак $9a-a^{3}$ только при $a\\ge0$, а при $a<0$ счёл правую часть отрицательной; на самом деле при $a<-3$ она положительна (два корня), а $a=-3$ даёт один корень."),
        2: (r"при $a \in (-\infty; -3) \cup (3; +\infty)$: $0$ корней; при $a = -3$, $a = 3$: $1$ корень; при $a \in (-3; 3)$: $2$ корня", "Ученик не разобрал знак $9a-a^{3}$ на $(-3;0)$, где оно отрицательно (корней нет), и отнёс $a=0$ к промежутку с двумя корнями, хотя при $a=0$ единственный корень $x=0$.")})
E("G10_TB_§7_6_21_4", r"$4^{n}>2^{n}$ при любом натуральном $n$: подходят и чётные, и нечётные показатели",
  k="и чётным, и нечётным",
  dnew={0: ("нечётным", "Ученик проверил только $n=1$ ($4>2$) и решил, что подходит лишь нечётный показатель, не проверив чётные: при $n=2$ тоже $16>4$."),
        1: ("чётным", "Ученик проверил только $n=2$ ($16>4$) и решил, что подходит лишь чётный показатель, не проверив $n=1$: $4>2$ тоже верно."),
        2: ("нельзя определить", "Ученик решил, что без значения $n$ вывод сделать нельзя, но не заметил, что $4^{n}>2^{n}$ при любом натуральном $n$.")})
E("G10_TB_§7_6_21_6", r"при чётном $n$: $4^{n}>2^{n}=(-2)^{n}$; при нечётном: $4^{n}>0>(-2)^{n}$; неравенство верно при любом натуральном $n$",
  k="и чётным, и нечётным",
  dnew={0: ("нечётным", "Ученик проверил только $n=1$ ($4>-2$) и решил, что подходит лишь нечётный показатель, не проверив чётные: при $n=2$ тоже $16>4$."),
        1: ("чётным", "Ученик проверил только $n=2$ ($16>4$) и решил, что подходит лишь чётный показатель, не проверив $n=1$: $4>-2$ тоже верно."),
        2: ("невозможно определить", "Ученик решил, что из-за отрицательного основания $-2$ знак сравнения зависит от $n$, но при любом натуральном $n$ верно $4^{n}>(-2)^{n}$.")})
